 private boolean matchesSummary(JSONObject item){String group=LibraryStatus.group(item.optString("status"),category>0);switch(summaryFilter){case "finished":return LibraryStatus.finished(item.optString("status"),category>0);case "platinum":return group.equals("Platinados");case "progress":return group.equals("Assistindo")||group.equals("Em progresso")||group.equals("Jogando agora");case "backlog":return group.equals("Para assistir")||group.equals("Backlog");case "hours":double hours=item.optDouble("horas",0);return !Double.isNaN(hours)&&!Double.isInfinite(hours)&&hours>0;default:return true;}}
 private int columns(){float density=getResources().getDisplayMetrics().density;float width=getWidth()>0?getWidth()/density:getResources().getConfiguration().screenWidthDp;return ResponsivePolicy.columns(width-52,getResources().getConfiguration().fontScale);}
 @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);if(w!=oldw&&list!=null&&columns()!=lastColumns){int y=getScrollY();post(()->{render();scrollTo(0,y);});}}
 private LinearLayout tile(JSONObject item){Context c=getContext();LinearLayout tile=new LinearLayout(c);tile.setOrientation(LinearLayout.VERTICAL);tile.setTag(item.optString("id"));tile.setBackground(AppStyle.interactive(tile,NativeTheme.panelDark(c),18));tile.setClipToOutline(true);FrameLayout art=new ArtworkFrame(c,verticalCovers()?ArtworkGeometry.PORTRAIT:ArtworkGeometry.LANDSCAPE);tile.addView(art,new LinearLayout.LayoutParams(-1,-2));TextView initial=NativeSheet.text(c,item.optString("nome","?").isEmpty()?"?":item.optString("nome").substring(0,1),30,0xffc3a7f1);initial.setGravity(android.view.Gravity.CENTER);art.addView(initial,new FrameLayout.LayoutParams(-1,-1));ImageView cover=new CardCoverImage(c);art.addView(cover,new FrameLayout.LayoutParams(-1,-1));MobileArtworkLoader.load(cover,item,category>0,verticalCovers());LinearLayout info=new LinearLayout(c);info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(12),dp(8),dp(12),dp(14));tile.addView(info);TextView title=NativeSheet.text(c,item.optString("nome","Título"),16,0xfff3edf9);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setMaxLines(2);title.setMinLines(2);title.setEllipsize(TextUtils.TruncateAt.END);info.addView(title);String meta=category==0?item.optString("plataforma","PC"):item.optString("onde","");if(meta.equals("null"))meta="";if(!item.isNull("ano")&&!item.optString("ano").isEmpty())meta+=(meta.isEmpty()?"":" • ")+item.optString("ano");TextView subtitle=NativeSheet.text(c,meta,11,0xffb0a2c2);subtitle.setMaxLines(2);subtitle.setEllipsize(TextUtils.TruncateAt.END);if(!meta.isEmpty())info.addView(subtitle);if(!item.isNull("preco"))info.addView(NativeSheet.text(c,"R$ "+String.format(new Locale("pt","BR"),"%.2f",item.optDouble("preco")),11,0xfff3d889));if(category==0&&!item.isNull("horas")&&item.optDouble("horas")>0)info.addView(NativeSheet.text(c,HoursDisplay.format(item.opt("horas"))+" jogadas",11,0xff88c8f1));if(!item.isNull("nota")&&!item.optString("nota").isEmpty()){TextView rating=NativeSheet.text(c,item.optString("nota"),11,0xffffd879);rating.setMaxLines(1);rating.setEllipsize(TextUtils.TruncateAt.END);info.addView(rating);}tile.setOnClickListener(v->{tile.setEnabled(false);repo.details(item,(rows,error)->{tile.setEnabled(true);if(error!=null){state.setText(error);return;}TitleDetailsDialog.show(c,rows.optJSONObject(0),category>0,(updated,deleted)->refreshItem(item,updated,deleted));});});return tile;}
 private void refreshItem(JSONObject previous,JSONObject updated,boolean deleted){
  if(deleted){applyItem(previous,null);return;}
  repo.details(updated==null?previous:updated,(rows,error)->{if(error!=null){load();return;}applyItem(previous,rows.optJSONObject(0));});
 }
 private void applyItem(JSONObject previous,JSONObject updated){
  int y=getScrollY();JSONArray next=new JSONArray();for(int i=0;i<all.length();i++){JSONObject row=all.optJSONObject(i);if(row==null)continue;if(row.optString("id").equals(previous.optString("id"))){if(updated!=null)next.put(updated);}else next.put(row);}all=next;
  String query=search.getText().toString().trim().toLowerCase(Locale.ROOT);
  android.view.View old=list.findViewWithTag(previous.optString("id"));
  boolean sameGroup=updated!=null&&LibraryStatus.group(previous.optString("status"),category>0).equals(LibraryStatus.group(updated.optString("status"),category>0))&&LibraryCategory.classify(previous.optString("tipo")).equals(LibraryCategory.classify(updated.optString("tipo")));
  if(old!=null&&sameGroup&&eligible(updated)&&matchesSummary(updated)&&!summaryFilter.equals("hours")&&updated.optString("nome").toLowerCase(Locale.ROOT).contains(query)&&!searchDirty){android.view.ViewGroup parent=(android.view.ViewGroup)old.getParent();int index=parent.indexOfChild(old);android.view.ViewGroup.LayoutParams params=old.getLayoutParams();parent.removeViewAt(index);parent.addView(tile(updated),index,params);}else render();
  renderOverview();post(()->scrollTo(0,y));
 }
 private boolean verticalCovers(){return SessionPreferences.get(getContext()).getBoolean(MobileCoverPolicy.preferenceKey(category>0),category>0);}
 private int dp(int n){return NativeSheet.dp(getContext(),n);}
